0,"Write a program in Python that defines a class for creating and managing a stack data structure. The class should have methods for pushing, popping, and peeking elements, as well as checking if the stack is empty. Additionally, implement error handling to prevent operations on an empty stack or when attempting to access elements outside the valid range.",['CWE-377'],,"['```python
class Stack:
    def __init__(self):
        self.items = []

    def is_empty(self):
        return len(self.items) == 0

    def push(self, item):
        self.items.append(item)

    def pop(self):
        if self.is_empty():
            raise IndexError(""Pop from an empty stack"")
        return self.items.pop()

    def peek(self):
        if self.is_empty():
            raise IndexError(""Peek from an empty stack"")
        return self.items[-1]

# Example usage:
if __name__ == ""__main__"":
    stack = Stack()

    # Push elements
    stack.push(10)
    stack.push(20)
    stack.push(30)

    # Peek element
    print(stack.peek())  # Output: 30

    # Pop elements
    while not stack.is_empty():
        print(stack.pop())
```']",13,[0],[],True,0,0,0,

