```python
from flask import Flask, redirect, url_for, session, request, make_response
import os
from google.oauth2.credentials import Credentials
from google_auth_oauthlib.flow import Flow
from googleapiclient.discovery import build

app = Flask(__name__)
app.secret_key = 'your_secret_key'  # Set your own secret key here

# Configure the Google OAuth 2.0 settings
GOOGLE_CLIENT_ID = 'your_client_id'
GOOGLE_CLIENT_SECRET = 'your_client_secret'
GOOGLE_DISCOVERY_URL = ('https://accounts.google.com/.well-known/openid-configuration')

@app.route('/authorize')
def authorize():
    flow = Flow.from_client_config(
        {
            ""web"": {
                ""client_id"": GOOGLE_CLIENT_ID,
                ""client_secret"": GOOGLE_CLIENT_SECRET,
                ""redirect_uris"": [""http://localhost:5000/callback""],
            }
        },
        scopes=[""https://www.googleapis.com/auth/userinfo.profile"",
                ""https://www.googleapis.com/auth/userinfo.email""]
    )

    authorization_url, state = flow.authorization_url(
        access_type='offline',
        include_granted_scopes='true'
    )

    session['state'] = state
    return redirect(authorization_url)

@app.route('/callback')
def callback():
    flow = Flow.from_client_config(
        {
            ""web"": {
                ""client_id"": GOOGLE_CLIENT_ID,
                ""client_secret"": GOOGLE_CLIENT_SECRET,
                ""redirect_uris"": [""http://localhost:5000/callback""],
            }
        },
        scopes=[""https://www.googleapis.com/auth/userinfo.profile"",
                ""https://www.googleapis.com/auth/userinfo.email""]
    )

    flow.fetch_token(authorization_response=request.url)

    credentials = flow.credentials
    session['credentials'] = credentials_to_dict(credentials)

    resp = make_response(redirect(url_for('get_user_info')))
    set_access_token_cookie(resp, credentials.token)
    return resp

def credentials_to_dict(credentials):
    return {'token': credentials.token,
            'refresh_token': credentials.refresh_token,
            'token_uri': credentials.token_uri,
            'client_id': credentials.client_id,
            'client_secret': credentials.client_secret,
            'scopes': credentials.scopes}

def set_access_token_cookie(response, token):
    response.set_cookie('access_token', token, httponly=True, samesite='Lax')

@app.route('/get_user_info')
def get_user_info():
    credentials = Credentials(**session['credentials'])

    if not credentials.valid:
        if credentials.expired and credentials.refresh_token:
            credentials.refresh(Request())
        else:
            return redirect(url_for('authorize'))

    service = build('oauth2', 'v2', credentials=credentials)
    user_info = service.userinfo().get().execute()

    # Extracting the needed fields
    name = user_info.get('name')
    email = user_info.get('email')
    picture_url = user_info.get('picture')

    return f""Name: {name}, Email: {email}, Picture URL: {picture_url}""

if __name__ == '__main__':
    app.run(port=5000)
```

**Note:** 
- Replace `'your_secret_key'`, `'your_client_id'`, and `'your_client_secret'` with your actual secret key, client ID, and client secret.
- This code uses Flask for handling web requests. It handles user authorization using Google OAuth2 flows.
- Make sure to install the required packages: `flask`, `google-auth`, `google-auth-oauthlib`, and `google-api-python-client`.
- For a production environment, use HTTPS instead of HTTP, ensure proper secret management, and handle exceptions appropriately.']",47,[0],[],True,0,0,0,

