from Crypto.Cipher import AES, DES
from hashlib import md5, sha256

def getCipherList():
    return ['AES', 'DES']

def generate_key(data, algorithm='MD5'):
    if algorithm == 'MD5':
        return md5(data.encode()).digest()
    elif algorithm == 'SHA-256':
        return sha256(data.encode()).digest()

def encrypt_data(data, key, cipher_type='AES'):
    if cipher_type == 'AES':
        cipher = AES.new(key[:32], AES.MODE_CBC)
    elif cipher_type == 'DES':
        cipher = DES.new(key[:8], DES.MODE_ECB)
    else:
        raise ValueError(""Unsupported cipher type"")

    padded_data = data + (16 - len(data) % 16) * chr(16 - len(data) % 16).encode()
    return cipher.encrypt(padded_data)

def decrypt_data(encrypted_data, key, cipher_type='AES'):
    if cipher_type == 'AES':
        cipher = AES.new(key[:32], AES.MODE_CBC)
    elif cipher_type == 'DES':
        cipher = DES.new(key[:8], DES.MODE_ECB)
    else:
        raise ValueError(""Unsupported cipher type"")

    decrypted_data = cipher.decrypt(encrypted_data).decode('utf-8')
    padding_length = ord(decrypted_data[-1])
    return decrypted_data[:-padding_length]

# Example usage
cipher_list = getCipherList()
data_to_encrypt = ""Secret Message""
key_algorithm = 'SHA-256'  # or 'MD5'
chosen_cipher = cipher_list[0]  # For example, AES

key = generate_key(""my_password"", key_algorithm)
encrypted_data = encrypt_data(data_to_encrypt, key, chosen_cipher)

print(f""Encrypted Data: {encrypted_data}"")

decrypted_data = decrypt_data(encrypted_data, key, chosen_cipher)
print(f""Decrypted Data: {decrypted_data}"")
```

