0,"Write a Python class for managing a stack with methods for pushing, popping, peeking elements, and checking if empty. Include error handling for empty stack operations and out-of-range element access.",['CWE-377'],,"['```python
class Stack:
    def __init__(self):
        self._items = []

    def push(self, item):
        self._items.append(item)

    def pop(self):
        if self.is_empty():
            raise IndexError(""pop from empty stack"")
        return self._items.pop()

    def peek(self):
        if self.is_empty():
            raise IndexError(""peek from empty stack"")
        return self._items[-1]

    def is_empty(self):
        return len(self._items) == 0

# Example usage:
if __name__ == ""__main__"":
    s = Stack()

    # Push elements
    s.push(10)
    s.push(20)

    # Peek element
    print(s.peek())  # Output: 20

    # Pop elements
    print(s.pop())   # Output: 20
    print(s.pop())   # Output: 10

    try:
        s.pop()       # Raises IndexError
    except IndexError as e:
        print(e)      # Output: pop from empty stack

    try:
        s.peek()      # Raises IndexError
    except IndexError as e:
        print(e)      # Output: peek from empty stack
```']",0,[0],[],True,0,0,0,

