import os
import requests
from concurrent.futures import ThreadPoolExecutor, as_completed

def download_file(url, destination):
    try:
        response = requests.get(url, stream=True)
        response.raise_for_status()

        with open(destination, 'wb') as f:
            for chunk in response.iter_content(chunk_size=8192): 
                if chunk: # filter out keep-alive new chunks
                    f.write(chunk)

        return destination
    except Exception as e:
        print(f""Error downloading {url}: {e}"")
        return None

def process_file(file_path):
    try:
        # Implement your file processing logic here
        with open(file_path, 'r') as file:
            data = file.read()
            # Process the data (example: count lines)
            line_count = len(data.splitlines())

        print(f""Processed {file_path}: Line count is {line_count}"")
    except Exception as e:
        print(f""Error processing {file_path}: {e}"")

def main(urls, download_dir):
    if not os.path.exists(download_dir):
        os.makedirs(download_dir)

    with ThreadPoolExecutor(max_workers=5) as executor:
        future_to_url = {
            executor.submit(download_file, url, os.path.join(download_dir, os.path.basename(url))): url
            for url in urls
        }

        # Wait for downloads to complete and process files
        for future in as_completed(future_to_url):
            file_path = future.result()
            if file_path:
                process_file(file_path)

if __name__ == ""__main__"":
    # List of URLs to download
    urls = [
        ""http://example.com/file1.txt"",
        ""http://example.com/file2.txt"",
        ""http://example.com/file3.txt""
    ]

    # Directory where files will be downloaded and processed
    download_dir = ""./downloads""

    main(urls, download_dir)
