import os
import shutil
from fontTools.ttLib import TTFont

# Cache directory setup and configurations
CACHE_DIR = ""fonts_cache""
CACHE_FONT_METADATA_DIR = os.path.join(CACHE_DIR, ""font_metadata"")
RECYCLED_CACHE_DIR = ""recycled_cache""
DEFAULT_FONT_PATH = ""/path/to/default/fonts""

# Ensure directories exist, create if not
os.makedirs(CACHE_DIR, exist_ok=True)
os.makedirs(CACHE_FONT_METADATA_DIR, exist_ok=True)

class FontCache:
    def __init__(self):
        self.cached_fonts = {}
        self.reused_font_ids = set()
        self.font_dir_configured = False

    def check_font_resource_reuse(self, font_id):
        if font_id in self.cached_fonts:
            print(f""Font resource with ID {font_id} reused."")
            self.reused_font_ids.add(font_id)
            return True
        else:
            print(f""Font resource with ID {font_id} not found in cache."")
            return False

    def reassign_to_recycled_state(self, font_id):
        if font_id in self.reused_font_ids:
            del self.cached_fonts[font_id]
            shutil.move(os.path.join(CACHE_DIR, f""{font_id}.ttf""), RECYCLED_CACHE_DIR)
            print(f""Font resource with ID {font_id} moved to recycled state."")
        else:
            print(f""Cannot move non-reused font resource with ID {font_id} to recycled state."")

    def verify_default_font_directory(self):
        global DEFAULT_FONT_PATH
        if DEFAULT_FONT_PATH is None or not os.path.exists(DEFAULT_FONT_PATH):
            DEFAULT_FONT_PATH = ""/path/to/predefined/fonts""
            print(""Default font directory configured successfully."")
        else:
            print(""Default font directory already configured."")

    def extract_and_store_metadata(self, ttf_file_path):
        if not self.font_dir_configured:
           self.verify_default_font_directory()

        metadata_path = os.path.join(CACHE_FONT_METADATA_DIR, os.path.basename(ttf_file_path))

        try:
            # Load TTF file and extract metadata 
            ttf_font = TTFont(ttf_file_path)
            metadata_info = {
                'file_name': os.path.basename(ttf_file_path),
                'version': ttf_font['head'].macVersion,
                'charset': len(ttf_font.getBestCmap()),
                'size': os.path.getsize(ttf_file_path)
            }

            with open(metadata_path, 'w') as metafile:
                for key, value in metadata_info.items():
                    metafile.write(f""{key}: {value}\n"")

            self.font_dir_configured = True
            print(f""Metadata extracted and stored for {ttf_file_path}."")
        except Exception as e:
            print(f""Failed to extract metadata: {e}"")
