import json

class JSONBase:
    _registry = {}

    @classmethod
    def register(cls, id_, constructor):
        cls._registry[id_] = constructor

    @classmethod
    def create_instance(cls, id_, *args, **kwargs):
        if id_ in cls._registry:
            return cls._registry[id_](*args, **kwargs)
        raise ValueError(f""No registered factory for ID: {id_}"")

    def to_json(self):
        return json.dumps(self.__dict__)

    @classmethod
    def from_json(cls, json_str):
        data = json.loads(json_str)
        id_ = data.pop('id', None)
        if id_ and id_ in cls._registry:
            return cls._registry[id_](**data)
        raise ValueError(f""No registered factory for ID: {id_}"")

# Example subclass
class SubClass(JSONBase):
    def __init__(self, attr1, attr2):
        self.attr1 = attr1
        self.attr2 = attr2

# Registering the subclass with an ID
JSONBase.register('subclass', SubClass)

# Usage example:
