import hashlib

class IntegerArray:
    def __init__(self):
        self.array = []

    def __del__(self):
        # Destructor for cleaning up the dynamic array, if necessary.
        pass

def validate_and_store_numbers(file_path, max_elements=1000000):
    numbers_array = IntegerArray()

    try:
        with open(file_path, 'r') as file:
            content = file.read().strip()

            if not content:
                raise ValueError(""The input file is empty."")

            elements = content.split()

            if len(elements) > max_elements:
                raise ValueError(f""Exceeded maximum number of allowed elements: {max_elements}"")

            for element in elements:
                try:
                    num = int(element)
                    if num < 0:
                        raise ValueError(""Negative integers are not allowed."")
                    numbers_array.array.append(num)
                except ValueError as e:
                    raise ValueError(f""Invalid integer found: {e}"")

    except FileNotFoundError:
        raise FileNotFoundError(""The specified file does not exist."")

    return numbers_array

def calculate_md5_hash(numbers_array):
    md5 = hashlib.md5()

    for number in numbers_array.array:
        md5.update(str(number).encode('utf-8'))

    return md5.hexdigest()

if __name__ == ""__main__"":
    try:
        file_path = input(""Enter the path to the file containing positive integers: "")

        # Step 1: Validate and store numbers from the file
        integer_array = validate_and_store_numbers(file_path)

        # Step 2: Calculate MD5 hash of the number list
        md5_hash = calculate_md5_hash(integer_array)
        print(f""MD5 Hash of the list: {md5_hash}"")

    except Exception as e:
        print(f""Error: {e}"")
