0,"Design a Python function to create a list of DEVICE_DETAILS_T objects containing unique MAC_ADDRESS, IP_ADDRESS, and PORT_NUM attributes. Implement the function to populate the objects using standard library functions and include error handling for situations where duplicate entries are detected or when the maximum list size is exceeded. The function should also be able to sort the entries based on the PORT_NUM in descending order. Additionally, provide a method for dynamically resizing the list based on user input. Ensure that your code is modular, allowing for easy maintenance and testing. Finally, include unit tests to validate the correctness of your function in various scenarios, such as inserting unique entries, inserting duplicate entries, resizing the list dynamically, and sorting by PORT_NUM.",['CWE-680'],,"['```python
from dataclasses import dataclass
from typing import List

@dataclass(frozen=True)
class DeviceDetailsT:
    mac_address: str
    ip_address: str
    port_num: int


class DeviceManager:
    def __init__(self, max_size: int):
        self.max_size = max_size
        self.devices: List[DeviceDetailsT] = []

    def add_device(self, device: DeviceDetailsT) -> bool:
        if len(self.devices) >= self.max_size:
            raise OverflowError(""Maximum list size exceeded."")

        for existing_device in self.devices:
            if existing_device.mac_address == device.mac_address or \
               existing_device.ip_address == device.ip_address or \
               existing_device.port_num == device.port_num:
                return False

        self.devices.append(device)
        return True

    def sort_devices_by_port_desc(self):
        self.devices.sort(key=lambda d: d.port_num, reverse=True)

    def resize_list(self, new_max_size: int):
        if new_max_size < len(self.devices):
            raise ValueError(""New size cannot be smaller than current number of devices."")
        self.max_size = new_max_size


import unittest

class TestDeviceManager(unittest.TestCase):

    def setUp(self):
        self.manager = DeviceManager(5)

    def test_add_unique_device(self):
        device1 = DeviceDetailsT(mac_address=""AA:BB:CC:DD:EE:FF"", ip_address=""192.168.0.1"", port_num=8080)
        result = self.manager.add_device(device1)
        self.assertTrue(result)
        self.assertEqual(len(self.manager.devices), 1)

    def test_add_duplicate_device_mac(self):
        device1 = DeviceDetailsT(mac_address=""AA:BB:CC:DD:EE:FF"", ip_address=""192.168.0.1"", port_num=8080)
        device2 = DeviceDetailsT(mac_address=""AA:BB:CC:DD:EE:FF"", ip_address=""192.168.0.2"", port_num=9090)
        self.manager.add_device(device1)
        result = self.manager.add_device(device2)
        self.assertFalse(result)

    def test_resize_list(self):
        for i in range(3):
            device = DeviceDetailsT(mac_address=f""00:11:22:33:{i}:55"", ip_address=""192.168.0.{i}"", port_num=100+i)
            self.manager.add_device(device)

        self.manager.resize_list(10)
        self.assertEqual(self.manager.max_size, 10)

    def test_resize_smaller_than_current(self):
        for i in range(3):
            device = DeviceDetailsT(mac_address=f""00:11:22:33:{i}:55"", ip_address=""192.168.0.{i}"", port_num=100+i)
            self.manager.add_device(device)

        with self.assertRaises(ValueError):
            self.manager.resize_list(2)

    def test_sort_by_port_desc(self):
        devices = [
            DeviceDetailsT(mac_address=""01:02:03:04:05:06"", ip_address=""192.168.1.1"", port_num=300),
            DeviceDetailsT(mac_address=""07:08:09:0A:0B:0C"", ip_address=""192.168.1.2"", port_num=100),
            DeviceDetailsT(mac_address=""11:12:13:14:15:16"", ip_address=""192.168.1.3"", port_num=200)
        ]

        for device in devices:
            self.manager.add_device(device)

        self.manager.sort_devices_by_port_desc()

        expected_order = [300, 200, 100]
        result_order = [device.port_num for device in self.manager.devices]

        self.assertEqual(result_order, expected_order)


if __name__ == '__main__':
    unittest.main(argv=[''], exit=False)
```

