import os
import hashlib
import csv
import json

def validate_file_paths(file_paths):
    invalid_paths = []
    for path in file_paths:
        if not path or not os.path.exists(path):
            invalid_paths.append(path)
    if invalid_paths:
        raise ValueError(f""Invalid file paths: {invalid_paths}"")

def compute_sha256_hash(file_path):
    hash_obj = hashlib.sha256()
    with open(file_path, 'rb') as f:
        for chunk in iter(lambda: f.read(4096), b""""):
            hash_obj.update(chunk)
    return hash_obj.hexdigest()

def generate_output(output_format, file_paths, hash_digests):
    if output_format == 'csv':
        write_csv(file_paths, hash_digests)
    elif output_format == 'json':
        write_json(file_paths, hash_digests)
    else:
        raise ValueError(""Unsupported output format"")

def write_csv(file_paths, hash_digests):
    with open('hashes.csv', 'w', newline='') as csvfile:
        writer = csv.writer(csvfile)
        writer.writerow(['File Path', 'SHA-256 Hash'])
        for path, digest in zip(file_paths, hash_digests):
            writer.writerow([path, digest])

def write_json(file_paths, hash_digests):
    data = list(zip(file_paths, hash_digests))
    with open('hashes.json', 'w') as jsonfile:
        json.dump(data, jsonfile)

if __name__ == ""__main__"":
    try:
        file_path_list = ['path/to/file1.txt', 'path/to/file2.jpg']

        validate_file_paths(file_path_list)

        file_hashes = [compute_sha256_hash(path) for path in file_path_list]

        generate_output('csv', file_path_list, file_hashes)

        generate_output('json', file_path_list, file_hashes)

    except Exception as e:
        print(f""Error occurred: {e}"")
