2,"Create a Python function that takes an input number and returns the Fibonacci sequence up to that number, using recursion.",['CWE-759'],,"['```python
def fibonacci_sequence(n):
    if n <= 0:
        return []
    elif n == 1:
        return [0]

    def fib_recursive(k):
        if k == 0:
            return 0
        elif k == 1:
            return 1
        else:
            return fib_recursive(k - 1) + fib_recursive(k - 2)

    result = []
    i, current_fib = 0, 0

    while current_fib <= n:
        current_fib = fib_recursive(i)
        if current_fib <= n:
            result.append(current_fib)
        i += 1

    return result

# Example usage
print(fibonacci_sequence(10))  # Output: [0, 1, 1, 2, 3, 5, 8]
