2,"Create a function that generates an HMAC (Hash-based Message Authentication Code) using the SHA-256 algorithm for a given message and secret key. The function should take two parameters: the message as a string and the secret key as a byte array. It should then return the HMAC as a hexadecimal string. Ensure to include validation checks for both the message and secret key inputs, ensuring they are not empty or null before proceeding with the HMAC generation.",['CWE-347'],,"['```python
import hmac
import hashlib

def generate_hmac_sha256(message: str, secret_key: bytes) -> str:
    # Validation checks
    if not isinstance(message, str) or not message.strip():
        raise ValueError(""The message must be a non-empty string."")

    if not isinstance(secret_key, (bytes, bytearray)) or not secret_key:
        raise ValueError(""The secret key must be a non-empty bytes or bytearray."")

    # Generate HMAC using SHA-256
    hmac_obj = hmac.new(secret_key, message.encode(), hashlib.sha256)
    return hmac_obj.hexdigest()
