import os
import requests
import logging
from cryptography.hazmat.primitives import serialization
from cryptography.hazmat.primitives.serialization import pkcs12, pkcs8, x509
from cryptography.hazmat.backends import default_backend
from datetime import datetime, timedelta

# Configure logging
logging.basicConfig(level=logging.INFO)

class CertificateManager:
    def __init__(self, cache_dir='cache', enable_encryption=False):
        self.cache_dir = cache_dir
        self.enable_encryption = enable_encryption
        os.makedirs(cache_dir, exist_ok=True)
        self.cache_expiry_time = timedelta(hours=1)  # Cache expiry time

    def fetch_and_convert(self, urls_or_paths, output_filename=None):
        try:
            private_key, cert_chain = [], []
            for source in urls_or_paths:
                if self._is_url(source):
                    data = requests.get(source).content
                else:
                    with open(source, 'rb') as file:
                        data = file.read()

                # Convert to PEM if necessary and cache
                key, chain = self._process_data(data)
                private_key.append(key)
                cert_chain.extend(chain)

            combined_pem = self._combine_to_pem(private_key[0], cert_chain)
            output_filename = output_filename or f""combined_{datetime.now().strftime('%Y%m%d%H%M%S')}.pem""

            with open(output_filename, 'wb') as file:
                file.write(combined_pem)

            logging.info(f""Combined PEM written to {output_filename}"")
        except Exception as e:
            logging.error(f""An error occurred: {e}"")

    def _is_url(self, source):
        return source.startswith('http://') or source.startswith('https://')

    def _process_data(self, data):
        try:
            # Check cache
            cached_key, cached_chain = self._check_cache(data)
            if cached_key and cached_chain:
                logging.info(""Using cached key and certificates"")
                return cached_key, cached_chain

            # Process private key
            if data.startswith(b'-----BEGIN PRIVATE KEY-----'):
                key_pem = data
            else:
                key_pem = self._convert_private_key(data)

            # Process certificate chain
            cert_chain = []
            for cert_data in self._split_certificates(data):
                if cert_data.startswith(b'-----BEGIN CERTIFICATE-----'):
                    cert_pem = cert_data
                else:
                    cert_pem = self._convert_certificate(cert_data)
                cert_chain.append(cert_pem)

            # Cache the results
            self._cache_result(key_pem, cert_chain)
            return key_pem, cert_chain

        except Exception as e:
            logging.error(f""Error processing data: {e}"")
            raise

    def _convert_private_key(self, data):
        try:
            if data.startswith(b'-----'):
                return data
            elif data[:2] == b'0\x02':  # DER format
                key = serialization.load_der_private_key(data, password=None, backend=default_backend())
            else:  # Assume PKCS#8
                key = serialization.load_pkcs8_data(data, None, default_backend())

            return key.private_bytes(
                encoding=serialization.Encoding.PEM,
                format=serialization.PrivateFormat.TraditionalOpenSSL,
                encryption_algorithm=serialization.NoEncryption()
            )
        except Exception as e:
            logging.error(f""Error converting private key: {e}"")
            raise

    def _convert_certificate(self, data):
        try:
            if data.startswith(b'-----'):
                return data
            cert = x509.load_der_x509_certificate(data, default_backend())
            return cert.public_bytes(serialization.Encoding.PEM)
        except Exception as e:
            logging.error(f""Error converting certificate: {e}"")
            raise

    def _combine_to_pem(self, private_key, cert_chain):
        return b''.join([private_key] + cert_chain)

    def _check_cache(self, data):
        cache_key = self._generate_cache_key(data)
        cache_path = os.path.join(self.cache_dir, cache_key)
        if os.path.exists(cache_path):
            with open(cache_path, 'rb') as file:
                cached_data = file.read().split(b'----END CERTIFICATE----')
                key_pem = cached_data[0] + b'----END PRIVATE KEY----'
                cert_chain = [cert + b'----END CERTIFICATE----' for cert in cached_data[1:]]
                if datetime.now() < self._get_cache_expiry_time(cache_path):
                    return key_pem, cert_chain
        return None, None

    def _cache_result(self, key_pem, cert_chain):
        cache_key = self._generate_cache_key(key_pem + b''.join(cert_chain))
        cache_path = os.path.join(self.cache_dir, cache_key)
        with open(cache_path, 'wb') as file:
            file.write(key_pem + b'----END CERTIFICATE----' + b'----END CERTIFICATE----'.join(cert_chain) + b'----END CERTIFICATE----')
        # Set expiry timestamp
        os.utime(cache_path, (datetime.now() + self.cache_expiry_time).timestamp())

    def _generate_cache_key(self, data):
        return hashlib.md5(data).hexdigest()

    def _get_cache_expiry_time(self, cache_path):
        _, mtime = os.stat(cache_path)
        return datetime.fromtimestamp(mtime) + self.cache_expiry_time

    def _split_certificates(self, data):
        # Dummy implementation for splitting certificates
        return [data]

