import base64
import requests
from cryptography.hazmat.primitives import serialization
from cryptography.hazmat.backends import default_backend
from cryptography import x509
from cryptography.x509.oid import NameOID, ExtendedKeyUsageOID, CertificatePoliciesOID, AuthorityInformationAccessOID

def fetch_certificate(url):
    try:
        response = requests.get(url)
        response.raise_for_status()
        return response.content
    except requests.exceptions.RequestException as e:
        print(f""Error downloading certificate: {e}"")
        return None

def pem_to_der(pem_content):
    der_content = pem_content.replace(""-----BEGIN CERTIFICATE-----"", """").replace(""-----END CERTIFICATE-----"", """")
    der_content = base64.b64decode(der_content)
    return der_content

def der_to_pem(der_content):
    pem_content = base64.b64encode(der_content).decode()
    pem_content = ""-----BEGIN CERTIFICATE-----\n"" + ""\n"".join([pem_content[i:i+64] for i in range(0, len(pem_content), 64)]) + ""\n-----END CERTIFICATE-----""
    return pem_content

def convert_format(certificate, format_type):
    if format_type == ""DER"":
        converted_certificate = pem_to_der(certificate)
    elif format_type == ""PEM"":
        converted_certificate = certificate

    return converted_certificate

def fetch_and_convert_certificates(urls, output_format=""PEM""):
    certificates = []

    for url in urls:
        certificate = fetch_certificate(url)

        if certificate:
            converted_certificate = convert_format(certificate, output_format)
            certificates.append(converted_certificate)

    return certificates

def check_crl(certificates):
    for cert_pem in certificates:
        cert_der = pem_to_der(cert_pem)
        cert = x509.load_der_x509_certificate(cert_der, default_backend())

        if hasattr(cert, 'crl_distribution_points') and cert.crl_distribution_points:
            for crl_dist_point in cert.crl_distribution_points:
                try:
                    crl_url = crl_dist_point.full_name[0].value
                    crl_response = requests.get(crl_url)

                    if crl_response.status_code == 200:
                        crl_data = crl_response.content
                        crl = x509.load_der_x509_crl(crl_data, default_backend())

                        for revoked_cert in crl:
                            if revoked_cert.serial_number == cert.serial_number:
                                print(f""Certificate with serial number {cert.serial_number} is revoked."")
                    else:
                        print(f""Failed to fetch CRL from {crl_url}. Status code: {crl_response.status_code}"")

                except Exception as e:
                    print(f""Error processing CRL for certificate {cert.subject}: {e}"")

