0,"Create a Python class designed to handle a stack, featuring functions for adding (pushing), removing (popping), viewing the top element (peeking), and determining if the stack is empty. Incorporate exception management to address issues arising from operations on an empty stack or attempts to access elements beyond the stack's bounds.",['CWE-377'],,"['```python
class Stack:
    def __init__(self):
        self.items = []

    def push(self, item):
        self.items.append(item)

    def pop(self):
        if not self.is_empty():
            return self.items.pop()
        else:
            raise IndexError(""Pop from an empty stack"")

    def peek(self):
        if not self.is_empty():
            return self.items[-1]
        else:
            raise IndexError(""Peek from an empty stack"")

    def is_empty(self):
        return len(self.items) == 0
