import os
from pathlib import Path

class FontCache:
    def __init__(self, font_dir=""/path/to/predefined/fonts""):
        self.cached_fonts = {}
        self.reused_font_ids = set()
        self.font_dir_configured = False

        # Set up directories
        self.cache_root = Path(""fonts_cache"")
        self.metadata_dir = self.cache_root / ""font_metadata""
        self.recycled_dir = self.cache_root / ""recycled_cache""

        os.makedirs(self.cache_root, exist_ok=True)
        os.makedirs(self.metadata_dir, exist_ok=True)
        os.makedirs(self.recycled_dir, exist_ok=True)

        # Set default font directory
        self.default_font_dir = Path(font_dir).resolve()
        if not self.font_dir_configured and self.default_font_dir.exists():
            self.font_dir_configured = True

    def check_resource_reuse(self, font_id):
        if font_id in self.cached_fonts:
            print(f""Font ID {font_id} reused."")
            self.reused_font_ids.add(font_id)
        else:
            print(f""Font ID {font_id} not found in cache."")

    def reassign_to_recycled_state(self, font_id):
        if font_id in self.reused_font_ids:
            font_file = Path(self.metadata_dir) / f""{font_id}.ttf""
            recycled_path = self.recycled_dir / font_file.name
            if font_file.exists():
                font_file.rename(recycled_path)
                print(f""Font ID {font_id} moved to recycled cache."")
                self.reused_font_ids.remove(font_id)
            else:
                print(""Error: Font file does not exist."")
        else:
            print(""Error: Font ID has not been reused."")

    def verify_default_font_directory(self):
        if not self.font_dir_configured:
            self.default_font_dir = Path(""/path/to/predefined/fonts"").resolve()
            print(f""Default font directory set to {self.default_font_dir}."")
            self.font_dir_configured = True

    def extract_and_store_metadata(self, font_file_name):
        # Ensure metadata extraction occurs only once
        if not self.font_dir_configured:
            return

        font_file_path = self.default_font_dir / font_file_name
        if font_file_path.exists():
            # Simulate metadata extraction (replace with actual logic)
            metadata = {
                ""file_name"": font_file_name,
                ""version"": ""1.0"",  # Example placeholder value
                ""charset_size"": 256  # Example placeholder value
            }

            # Store the extracted metadata
            metadata_path = self.metadata_dir / f""{font_file_name}.meta""
            with open(metadata_path, 'w') as meta_file:
                for key, value in metadata.items():
                    meta_file.write(f""{key}: {value}\n"")

            print(f""Metadata for {font_file_name} stored."")
        else:
            print(""Error: Font file does not exist."")

# Example usage
if __name__ == ""__main__"":
    font_cache = FontCache()
    font_cache.verify_default_font_directory()

    # Simulate caching a font by extracting metadata
    example_font_name = ""example.ttf""
