import os
import json
import requests

from google.oauth2.credentials import Credentials
from google_auth_oauthlib.flow import InstalledAppFlow

class CustomRandomGenerator:
    def __init__(self, min_value, max_value):
        self.min_value = min_value
        self.max_value = max_value

    def generate_random_float(self):
        return round(random.uniform(self.min_value, self.max_value), 2)

def authenticate_google_user():
    SCOPES = ['https://www.googleapis.com/auth/userinfo.email']
    creds = None

    if os.path.exists('token.json'):
        with open('token.json', 'r') as token:
            creds = Credentials.from_authorized_user_info(json.load(token), SCOPES)

    if not creds or not creds.valid:
        if creds and creds.expired and creds.refresh_token:
            creds.refresh(Request())
        else:
            flow = InstalledAppFlow.from_client_secrets_file('credentials.json', SCOPES)
            creds = flow.run_local_server(port=0)

        with open('token.json', 'w') as token:
            token.write(creds.to_json())

    return creds.token

def fetch_user_details(access_token):
    url = ""https://www.googleapis.com/oauth2/v3/userinfo""
    headers = {'Authorization': f'Bearer {access_token}'}

    response = requests.get(url, headers=headers)

    if response.status_code == 200:
        return response.json()
    else:
        return None

def generate_random_number(min_value, max_value):
    if min_value >= max_value:
        raise ValueError(""Minimum value must be less than maximum value."")

    random_generator = CustomRandomGenerator(min_value, max_value)

    return random_generator.generate_random_float()

def custom_random_generator_with_google_auth():
    access_token = authenticate_google_user()

    if access_token:
        user_details = fetch_user_details(access_token)

        if user_details:
            print(f""Welcome, {user_details['name']}! Your email is {user_details['email']}."")

            min_val = float(input(""Enter minimum value: ""))
            max_val = float(input(""Enter maximum value: ""))

            try:
                generated_number = generate_random_number(min_val, max_val)
                print(f""The generated random number is {generated_number}."")

            except ValueError as e:
                print(e)
        else:
            print(""Failed to retrieve user details."")
