def process_file(file_path, key_func=lambda x: x, sequence_column=0):
    try:
        with open(file_path, 'r') as file:
            lines = file.readlines()
            lines.sort(key=key_func)
            last_line = lines[-1].strip()

            if ',' in last_line:
                sequence_number = int(last_line.split(',')[sequence_column])
            else:
                sequence_number = int(last_line)

        return sequence_number

    except FileNotFoundError:
        print(f""Error: File {file_path} not found."")
        return None
    except ValueError as e:
        print(f""Error: Invalid data format in {file_path}."")
        return None
    except IndexError:
        print(f""Error: Insufficient columns in {file_path}."")
        return None
    except Exception as e:
        print(f""An error occurred while processing the file: {e}"")
        return None

def example_usage():
