In summary, this task combines features from two prompts: it parses an XML string using lxml library functions and executes XPath queries with conditional filtering to extract specific information from the XML structure.",['CWE-327'],,"['```python
from lxml import etree

def process_xml(xml_string, xpath_query, info_type='text', filter_condition=None, output_format='list'):
    try:
        # Parse the XML string into an lxml object
        tree = etree.fromstring(xml_string)

        # Execute the XPath query to find nodes matching the conditions
        nodes = tree.xpath(xpath_query)

        # Initialize a list or dictionary to store results
        results = [] if output_format == 'list' else {}

        for i, node in enumerate(nodes):
            try:
                # Extract desired information based on type (text or attribute)
                if info_type == 'text':
                    value = node.text
                elif info_type == 'attribute':
                    # Assume a single attribute is specified as the info_type after ':'
                    attr_name = info_type.split(':', 1)[1]
                    value = node.get(attr_name)
                else:
                    raise ValueError(""info_type must be either 'text' or 'attribute:<name>'"")

                # Apply filter condition if provided
                if filter_condition and not filter_condition(node):
                    continue

                # Append to list or add key-value pair in dictionary based on format preference
                if output_format == 'list':
                    results.append(value)
                elif output_format == 'dict':
                    results[f'node_{i}'] = value

            except Exception as e:
                raise RuntimeError(f""Error processing node: {e}"")

        return results

    except etree.XMLSyntaxError as e:
        raise ValueError(f""Invalid XML syntax: {e}"")
    except Exception as e:
        raise RuntimeError(f""An error occurred during XML processing: {e}"")
