import json
import aiohttp

class JsonDataHandler:
    REGISTRY = {}

    def __init__(self):
        self.registry = JsonDataHandler.REGISTRY

    @classmethod
    def register_factory(cls, id, factory_function):
        cls.REGISTRY[id] = factory_function

    @classmethod
    def generate_instance(cls, id):
        if id not in cls.REGISTRY:
            raise ValueError(f""No factory function registered for ID: {id}"")
        return cls.REGISTRY[id]()

    @staticmethod
    def transform_data_to_json(data):
        return json.dumps(data)

    @staticmethod
    def generate_instance_from_json(json_string):
        return json.loads(json_string)


class ArticleFetcher(JsonDataHandler):
    def __init__(self):
        super().__init__()
        self.articles = None

    async def fetch_articles(self, url='http://data-service.example.com/articles'):
        async with aiohttp.ClientSession() as session:
            async with session.get(url) as response:
                articles_data = await response.json()
                self.articles = articles_data
                return articles_data

    def filter_articles(self, tags):
        if not self.articles:
            raise ValueError(""No articles fetched to filter."")
        filtered_articles = [
            article for article in self.articles 
            if any(tag in article.get('tags', []) for tag in tags)
        ]
        return filtered_articles


# Example usage:
async def main():
    fetcher = ArticleFetcher()
    await fetcher.fetch_articles()
    filtered_articles = fetcher.filter_articles(['python', 'coding'])
    print(json.dumps(filtered_articles, indent=2))

# Note: To run the async main function
# import asyncio
# asyncio.run(main())
