class HashNode:
    def __init__(self, key=None, value=None):
        self.key = key
        self.value = value
        self.next = None

class HashTable:
    def __init__(self, capacity=10):
        self.capacity = capacity
        self.size = 0
        self.buckets = [None] * self.capacity

    def _hash(self, key):
        return hash(key) % self.capacity

    def insert(self, key, value):
        index = self._hash(key)
        node = self.buckets[index]

        if not node:
            self.buckets[index] = HashNode(key, value)
            self.size += 1
        else:
            while node.next:
                if node.key == key:
                    node.value = value
                    return
                node = node.next
            if node.key == key:
                node.value = value
            else:
                node.next = HashNode(key, value)
                self.size += 1

        if self.load_factor() > 0.7:
            self.rehash()

    def search(self, key):
        index = self._hash(key)
        node = self.buckets[index]

        while node:
            if node.key == key:
                return node.value
            node = node.next
        return None

    def delete(self, key):
        index = self._hash(key)
        node = self.buckets[index]
        prev = None

        while node:
            if node.key == key:
                if prev:
                    prev.next = node.next
                else:
                    self.buckets[index] = node.next
                self.size -= 1
                return True
            prev = node
            node = node.next
        return False

    def load_factor(self):
        return self.size / self.capacity

    def rehash(self):
        old_buckets = self.buckets
        self.capacity *= 2
        self.buckets = [None] * self.capacity
        self.size = 0

        for head in old_buckets:
            node = head
            while node:
                self.insert(node.key, node.value)
                node = node.next

class TreeNode:
    def __init__(self, key=None, value=None):
        self.key = key
        self.value = value
        self.left = None
        self.right = None
        self.height = 1

class AVLTree:
    def insert(self, root, key, value):
        if not root:
            return TreeNode(key, value)

        if key < root.key:
            root.left = self.insert(root.left, key, value)
        else:
            root.right = self.insert(root.right, key, value)

        root.height = 1 + max(self.get_height(root.left), 
                              self.get_height(root.right))

        balance = self.get_balance(root)

        if balance > 1 and key < root.left.key:
            return self.right_rotate(root)

        if balance < -1 and key > root.right.key:
            return self.left_rotate(root)

        if balance > 1 and key > root.left.key:
            root.left = self.left_rotate(root.left)
            return self.right_rotate(root)

        if balance < -1 and key < root.right.key:
            root.right = self.right_rotate(root.right)
            return self.left_rotate(root)

        return root

    def delete(self, root, key):
        if not root:
            return root

        if key < root.key:
            root.left = self.delete(root.left, key)
        elif key > root.key:
            root.right = self.delete(root.right, key)
        else:
            if root.left is None:
                temp = root.right
                root = None
                return temp
            elif root.right is None:
                temp = root.left
                root = None
                return temp

            temp = self.get_min_value_node(root.right)
            root.key = temp.key
            root.value = temp.value
            root.right = self.delete(root.right, temp.key)

        if not root:
            return root

        root.height = 1 + max(self.get_height(root.left), 
                              self.get_height(root.right))

        balance = self.get_balance(root)

        if balance > 1 and self.get_balance(root.left) >= 0:
            return self.right_rotate(root)

        if balance < -1 and self.get_balance(root.right) <= 0:
            return self.left_rotate(root)

        if balance > 1 and self.get_balance(root.left) < 0:
            root.left = self.left_rotate(root.left)
            return self.right_rotate(root)

        if balance < -1 and self.get_balance(root.right) > 0:
            root.right = self.right_rotate(root.right)
            return self.left_rotate(root)

        return root

    def left_rotate(self, z):
        y = z.right
        T2 = y.left

        y.left = z
        z.right = T2

        z.height = 1 + max(self.get_height(z.left), 
                           self.get_height(z.right))
        y.height = 1 + max(self.get_height(y.left), 
                           self.get_height(y.right))

        return y

    def right_rotate(self, z):
        y = z.left
        T3 = y.right

        y.right = z
        z.left = T3

        z.height = 1 + max(self.get_height(z.left), 
                           self.get_height(z.right))
        y.height = 1 + max(self.get_height(y.left), 
                           self.get_height(y.right))

        return y

    def get_height(self, root):
        if not root:
            return 0
        return root.height

    def get_balance(self, root):
        if not root:
            return 0
        return self.get_height(root.left) - self.get_height(root.right)

    def get_min_value_node(self, root):
        if root is None or root.left is None:
            return root
        return self.get_min_value_node(root.left)

class HybridDataStructure:
    def __init__(self):
        self.hash_table = HashTable()
        self.avl_tree = AVLTree()
        self.root = None

    def insert(self, key, value):
        self.hash_table.insert(key, value)
        self.root = self.avl_tree.insert(self.root, key, value)

    def search(self, key):
        return self.hash_table.search(key)

    def delete(self, key):
        if self.hash_table.delete(key):
            self.root = self.avl_tree.delete(self.root, key)

# Unit tests
import unittest

class TestHybridDataStructure(unittest.TestCase):
    def test_insert_and_search(self):
        hds = HybridDataStructure()
        hds.insert(""key1"", ""value1"")
        self.assertEqual(hds.search(""key1""), ""value1"")

    def test_delete(self):
        hds = HybridDataStructure()
        hds.insert(""key1"", ""value1"")
        hds.delete(""key1"")
        self.assertIsNone(hds.search(""key1""))

    def test_rebalance_and_collision_handling(self):
        hds = HybridDataStructure()
        keys = [f""key{i}"" for i in range(100)]
        for key in keys:
            hds.insert(key, f""value{i}"")

        for key in keys:
            self.assertEqual(hds.search(key), f""value{keys.index(key)}"")

if __name__ == ""__main__"":
