import hashlib

class TreeNode:
    def __init__(self, key, value):
        self.key = key
        self.value = [value]
        self.left = None
        self.right = None
        self.height = 1

class AVLTreeHashTable:
    def __init__(self, initial_capacity=8):
        self.capacity = initial_capacity
        self.size = 0
        self.load_factor_threshold = 0.75
        self.table = [None] * self.capacity

    def _hash(self, key):
        return int(hashlib.sha256(key.encode()).hexdigest(), 16) % self.capacity

    def _rebalance_insert(self, node):
        # Implement AVL Tree insert rebalance logic here.
        pass

    def _rebalance_delete(self, node):
        # Implement AVL Tree delete rebalance logic here.
        pass

    def _update_height(self, node):
        if not node:
            return 0
        left_height = self._update_height(node.left)
        right_height = self._update_height(node.right)
        node.height = max(left_height, right_height) + 1
        return node.height

    def _insert_avl(self, root, key, value):
        if not root:
            return TreeNode(key, value)

        if key < root.key:
            root.left = self._insert_avl(root.left, key, value)
        elif key > root.key:
            root.right = self._insert_avl(root.right, key, value)
        else:  # Duplicate key
            root.value.append(value)
            return root

        root.height = max(self._update_height(root.left), self._update_height(root.right)) + 1
        balance_factor = self._get_balance(root)

        if balance_factor > 1 and key < root.left.key:
            return self._rotate_right(root)

        if balance_factor < -1 and key > root.right.key:
            return self._rotate_left(root)

        if balance_factor > 1 and key > root.left.key:
            root.left = self._rotate_left(root.left)
            return self._rotate_right(root)

        if balance_factor < -1 and key < root.right.key:
            root.right = self._rotate_right(root.right)
            return self._rotate_left(root)

        return root

    def _get_balance(self, node):
        if not node:
            return 0
        return self._update_height(node.left) - self._update_height(node.right)

    def _rotate_left(self, z):
        y = z.right
        T2 = y.left

        y.left = z
        z.right = T2

        z.height = max(self._update_height(z.left), self._update_height(z.right)) + 1
        y.height = max(self._update_height(y.left), self._update_height(y.right)) + 1

        return y

    def _rotate_right(self, z):
        y = z.left
        T3 = y.right

        y.right = z
        z.left = T3

        z.height = max(self._update_height(z.left), self._update_height(z.right)) + 1
        y.height = max(self._update_height(y.left), self._update_height(y.right)) + 1

        return y

    def insert(self, key, value):
        index = self._hash(key)

        if not self.table[index]:
            self.table[index] = None

        if not self.table[index]:
            self.table[index] = TreeNode(key, value)
        else:
            self.table[index] = self._insert_avl(self.table[index], key, value)

        self.size += 1
        if self.load_factor() > self.load_factor_threshold:
            self._rehash()

    def load_factor(self):
        return self.size / float(self.capacity)

    def _rehash(self):
        old_table = self.table
        self.capacity *= 2
        self.table = [None] * self.capacity
        self.size = 0

        for node in old_table:
            if node is not None:
                self._reinsert(node)

    def _reinsert(self, node):
        keys_to_insert = [(node.key, val) for val in node.value]

        while keys_to_insert:
            key, value = keys_to_insert.pop(0)
            self.insert(key, value)

    def delete(self, key):
        index = self._hash(key)
        if not self.table[index]:
            raise KeyError(""Key not found."")

        # AVL Tree deletion logic would be implemented here
        pass

    def _in_order_traversal(self, node):
        if not node:
            return []
        return (self._in_order_traversal(node.left) +
                [(node.key, node.value)] +
                self._in_order_traversal(node.right))

    def traverse_bst_in_order(self):
        result = []
        for node in self.table:
            if node is not None:
                result.extend(self._in_order_traversal(node))
        return result

# Unit Tests
def test_avl_tree_hash_table():
    ht = AVLTreeHashTable()

    # Test insertions and load factor based resizing
    for i in range(10):
        ht.insert(f'key{i}', f'value{i}')

    assert len(ht.traverse_bst_in_order()) == 10

    # Test duplicate key handling
    ht.insert('key1', 'value_new')
    assert len([v for k, v in ht.traverse_bst_in_order() if k == 'key1']) == 2

    # Test deletion (placeholder as logic needs implementation)
