import random
import json
from multiprocessing import Pool
import threading

def validate_ip(ip, version=4):
    octets = ip.split('.')
    if len(octets) != version:
        return False
    try:
        return all(0 <= int(octet) < 256 for octet in octets)
    except ValueError:
        return False

def generate_ip(subnet_id, custom_range=None, version=4):
    if custom_range is None:
        custom_range = [(0, 255)] * (version - len(subnet_id)) + [(int(octet), int(octet)) for octet in subnet_id.split('.')]

    ip_address = '.'.join(
        str(random.randint(start, end)) for start, end in custom_range
    )
    return f""{subnet_id}.{ip_address}""

def generate_random_ip_addresses(subnet_id, count=1, version=4, custom_range=None):
    if not isinstance(subnet_id, (int, str)):
        raise ValueError(""Invalid subnet ID. Must be an integer or a string of two octets."")

    if isinstance(subnet_id, int):
        subnet_id = f""{subnet_id >> 8 & 255}.{subnet_id & 255}""

    if not isinstance(count, int) or count <= 0:
        raise ValueError(""Count must be a positive integer."")

    def worker(_):
        while True:
            ip_address = generate_ip(subnet_id, custom_range, version)
            if validate_ip(ip_address, version):
                return f""{ip_address} - Subnet ID: {subnet_id}""

    with Pool() as pool:
        ips = pool.map(worker, range(count))

    for ip in ips:
        print(f""IP Address: {ip}"")

    save_to_file(ips)

def save_to_file(ip_addresses):
    data = [{""IP"": ip.split(' - ')[0], ""Subnet ID"": ip.split(' - ')[1]} for ip in ip_addresses]
    with open(""generated_ips.json"", ""w"") as file:
        json.dump(data, file, indent=4)

# Example usage
generate_random_ip_addresses(""192.168"", 5)
```

