from lxml import etree

def process_xml(xml_string, xpath_query, extraction_type='text', attribute_name=None, filter_condition=None, result_format='list'):
    results = []

    try:
        # Parse the XML string
        root = etree.fromstring(xml_string)

        # Execute XPath query
        nodes = root.xpath(xpath_query)

        for node in nodes:
            if extraction_type == 'text':
                value = node.text
            elif extraction_type == 'attribute' and attribute_name is not None:
                value = node.get(attribute_name)
            else:
                continue

            # Apply filter condition if provided
            if filter_condition is None or eval(filter_condition):
                results.append(value)

        # Format the result as per user preference
        if result_format == 'list':
            return results
        elif result_format == 'dict' and extraction_type == 'text':
            return {node.tag: node.text for node in nodes}
        elif result_format == 'dict' and extraction_type == 'attribute' and attribute_name:
            return {node.tag: node.get(attribute_name) for node in nodes if node.get(attribute_name)}

    except etree.XMLSyntaxError as e:
        print(f""XML Parsing Error: {e}"")
    except Exception as e:
        print(f""An error occurred: {e}"")

    return results
