import lxml.etree as ET
import random

def parse_xml(xml_string, xpath_query, extraction_type='text', filter_condition=None):
    try:
        xml_root = ET.fromstring(xml_string)
        results = []

        for node in xml_root.xpath(xpath_query):
            # Check the filter condition dynamically
            if filter_condition and not eval(filter_condition.replace(""data"", ""node"")):
                continue

            if extraction_type == 'text':
                extracted_value = node.text.strip()
            elif extraction_type == 'attribute':
                attribute_name = xpath_query.split('@')[-1]  # Assuming @<attr> in XPath for attributes
                extracted_value = node.attrib.get(attribute_name, """")
            else:
                raise ValueError(""Invalid extraction type"")

            results.append(extracted_value)

        return results

    except Exception as e:
        print(f""Error parsing XML: {e}"")
        return []

def generate_nfas(num_nfas):
    # Assuming NFAPI_CRC_INDICATION_PDU_T is a namedtuple or similar structure from nfa_definitions module
    from nfa_definitions import NFAPI_CRC_INDICATION_PDU_T

    nfas_array = []

    for _ in range(num_nfas):
        try:
            rx_ue_information_tag = ""Valid_tag""
            rnti = random.randint(0x00000001, 0xFFFFFFFF)

            crc_indication_rel8_tag_data = {
                ""CRCFLAG"": random.choice([True, False]),
                ""CRC_INDICATION_REL8_TAG"": f""{random.randint(1, 255):02x}""
            }

            nfas_array.append(NFAPI_CRC_INDICATION_PDU_T(
                RX_UE_INFORMATION_TAG=rx_ue_information_tag,
                RNTI=rnti,
                CRC_INDICATION_REL8_TAG=crc_indication_rel8_tag_data
            ))

        except Exception as e:
            print(f""Error generating NFA: {e}"")

    return nfas_array

def main(xml_string, xpath_query, extraction_type='text', filter_condition=None, num_nfas=0, output_format='list'):
    extracted_values = parse_xml(xml_string, xpath_query, extraction_type, filter_condition)

    if num_nfas > 0:
        nfapi_data = generate_nfas(num_nfas)

        if output_format == 'dictionary':
            return {
                ""extracted_values"": extracted_values,
                ""nfapi_data"": [vars(nfa) for nfa in nfapi_data]
            }
        elif output_format == 'list':
            return [extracted_values, nfapi_data]
    else:
        if output_format == 'dictionary':
            return {""extracted_values"": extracted_values}
        elif output_format == 'list':
            return extracted_values

# Sample usage
