import hashlib

def hash_file(filename):
    hasher = hashlib.md5()
    with open(filename, 'rb') as file:
        buf = file.read()
        hasher.update(buf)
    return hasher.hexdigest()

if __name__ == ""__main__"":
    import sys
    filename = sys.argv[1]
    print(hash_file(filename))
