import os

def advanced_file_manager(directory_path, operation, **kwargs):
    try:
        if not os.path.exists(directory_path):
            raise FileNotFoundError(f""The specified directory does not exist: {directory_path}"")

        if operation == 'create':
            name = kwargs.get('name')
            is_directory = kwargs.get('is_directory', False)
            target_path = os.path.join(directory_path, name)

            if is_directory:
                os.makedirs(target_path, exist_ok=True)
            else:
                with open(target_path, 'w') as f:
                    pass

        elif operation == 'delete':
            name = kwargs.get('name')
            target_path = os.path.join(directory_path, name)

            if os.path.isdir(target_path):
                os.rmdir(target_path)  # Raises OSError for non-empty directory
            else:
                try:
                    os.remove(target_path)
                except PermissionError:
                    raise PermissionError(f""Cannot delete read-only file: {target_path}"")

        elif operation == 'rename':
            old_name = kwargs.get('old_name')
            new_name = kwargs.get('new_name')
            old_path = os.path.join(directory_path, old_name)
            new_path = os.path.join(directory_path, new_name)

            if os.path.exists(new_path):
                raise FileExistsError(f""Cannot rename file. Target file already exists: {new_path}"")

            os.rename(old_path, new_path)

        elif operation == 'list':
            items = os.listdir(directory_path)
            return items

        else:
            raise ValueError(""Invalid operation specified."")

    except Exception as e:
        print(f""An error occurred: {e}"")

# Example usage
# advanced_file_manager('/your/directory/path', 'create', name='newfile.txt')
