import json
import threading
import random

def validate_ip(ip_str):
    octets = ip_str.split('.')
    if len(octets) != 4:
        return False
    for octet in octets:
        if not octet.isdigit() or int(octet) < 0 or int(octet) > 255:
            return False
    return True

def generate_random_ip_addresses(subnet_id, count, ip_version='v4', start_octet=0, end_octet=255):
    if not isinstance(subnet_id, int) or not isinstance(count, int) or count <= 0:
        raise ValueError(""Invalid input: subnet_id must be an integer and count must be a positive integer"")

    def generate_ip():
        generated_ip = []
        for _ in range(4):
            generated_ip.append(str(random.randint(start_octet, end_octet)))
        return '.'.join(generated_ip)

    results = []

    def save_result():
        result = generate_random_ipv_x(ip_version)
        if validate_ip(result) or ip_version == 'v6':
            results.append({""IP Address"": result, ""Subnet ID"": subnet_id})

    threads = []

    for _ in range(count):
        thread = threading.Thread(target=save_result)
        thread.start()
        threads.append(thread)

    for thread in threads:
        thread.join()

    with open(f'generated_ips_{subnet_id}.json', 'w') as file:
        json.dump(results, file)

def generate_random_ipv_x(ip_version):
    if ip_version == 'v6':
