        return ':'.join([f""{random.randint(0, 65535):x}"" for _ in range(8)])
    else:
        generated_ip = f""{random.randint(start_octet, end_octet)}.{random.randint(0, 255)}."" \
                       f""{random.randint(0, 255)}.{random.randint(0, 255)}""
        return generated_ip

