import random

def generate_unique_random_integers(N):
    if N > (1 << 64):
        raise ValueError(""N cannot be greater than the number of unique 64-bit integers."")

    numbers = set()

    while len(numbers) < N:
        num = random.getrandbits(64)
        numbers.add(num)

    return list(numbers)

def check_all_distinct(arr):
    return len(arr) == len(set(arr))

# Example usage
N = 10
random_integers = generate_unique_random_integers(N)
assert check_all_distinct(random_integers), ""Generated integers are not distinct.""
print(random_integers)
```']",0,[0],[],True,0,0,0,

