0,"Create a Python function that processes a JSON string and extracts specific data based on given criteria. The function should accept parameters for the JSON query, extraction type (key or value), filter condition, number of JSON objects to extract, and return a list or dictionary based on user preference. Implement the function using the json library for parsing the JSON string and handling the extraction logic.",['CWE-327'],,"['```python
import json

def process_json(json_string, query_key=None, extraction_type='key', filter_condition=None, num_objects=1, return_format='list'):
    data = json.loads(json_string)

    if not isinstance(data, list):
        raise ValueError(""JSON string must represent a list of objects"")

    filtered_data = []

    for obj in data:
        if query_key and query_key not in obj:
            continue

        key_value = obj.get(query_key) if query_key else None
        value_to_check = key_value if extraction_type == 'key' else obj[query_key]

        if filter_condition is None or filter_condition(value_to_check):
            filtered_data.append(obj)
            if len(filtered_data) >= num_objects:
                break

    if return_format == 'list':
        result = [item for item in filtered_data[:num_objects]]
    elif return_format == 'dictionary':
        result = {idx: item for idx, item in enumerate(filtered_data[:num_objects])}
    else:
        raise ValueError(""Invalid return format. Use 'list' or 'dictionary'."")

    return result

# Example usage:
json_str = '[{""name"": ""Alice"", ""age"": 30}, {""name"": ""Bob"", ""age"": 25}, {""name"": ""Charlie"", ""age"": 35}]'
print(process_json(json_str, query_key=""age"", extraction_type='value', filter_condition=lambda x: x > 28, num_objects=2, return_format='list'))
```']",280,[0],[],True,0,0,0,

