import random
import string
from datetime import datetime

class NODE_BCCH_T:
    def __init__(self, BCCH_TYPE, BCCH_DL_SLOT, BCCH_PHY_RB, BCCH_SF_INDEX):
        self.BCCH_TYPE = BCCH_TYPE
        self.BCCH_DL_SLOT = BCCH_DL_SLOT
        self.BCCH_PHY_RB = BCCH_PHY_RB
        self.BCCH_SF_INDEX = BCCH_SF_INDEX

class DeviceContext:
    def __init__(self, DeviceId, ipAddress, port, last_heartbeat):
        self.DeviceId = DeviceId
        self.ipAddress = ipAddress
        self.port = port
        self.last_heartbeat = last_heartbeat

def generate_random_device_id():
    return ''.join(random.choices(string.ascii_letters + string.digits, k=8))

def generate_random_ip_address():
    return '.'.join(str(random.randint(0, 255)) for _ in range(4))

def create_node_bcch_array_and_device_context_list():
    node_bcch_array = [
        NODE_BCCH_T(
            BCCH_TYPE=random.choice([1, 2, 3]),
            BCCH_DL_SLOT=random.randint(1, 100),
            BCCH_PHY_RB=random.randint(1, 50),
            BCCH_SF_INDEX=random.randint(1, 10)
        ) for _ in range(5)
    ]

    device_context_list = [
        DeviceContext(
            DeviceId=generate_random_device_id(),
            ipAddress=generate_random_ip_address(),
            port=random.randint(1024, 65535),
            last_heartbeat=datetime.now().strftime('%Y-%m-%d %H:%M:%S')
        ) for _ in range(3)
    ]

    return node_bcch_array, device_context_list

# Example usage
node_bcch_array, device_context_list = create_node_bcch_array_and_device_context_list()

for i, node in enumerate(node_bcch_array):
    print(f""NODE_BCCH_T {i}: Type={node.BCCH_TYPE}, Slot={node.BCCH_DL_SLOT}, RB={node.BCCH_PHY_RB}, SF_Index={node.BCCH_SF_INDEX}"")

for j, device in enumerate(device_context_list):
    print(f""DeviceContext {j}: ID={device.DeviceId}, IP={device.ipAddress}, Port={device.port}, LastHeartbeat={device.last_heartbeat}"")
