def generate_network_status_reports(num_reports):
    operational_flags = ['UP', 'DOWN', 'MAINTENANCE']

    def get_random_node_id():
        return f""NODE_{random.randint(1000, 9999)}""

    def get_random_port_number():
        return random.randint(1, 65535)

    reports = []
    for _ in range(num_reports):
        node_id = get_random_node_id()
        port_number = get_random_port_number()
        operational_status_tag = random.choice(operational_flags)

        report = {
            'NODE_ID': node_id,
            'PORT_NUMBER': port_number,
            'OPERATIONAL_STATUS_TAG': operational_status_tag
        }
        reports.append(report)

    return reports

# Example usage:
