import random
import string

def generate_socket_receive_ucis(num_structs):
    def get_random_socket_id():
        return f""SOCKET_{random.randint(1000, 9999)}""

    def generate_session_token(length=16):
        return ''.join(random.choices(string.ascii_letters + string.digits, k=length))

    def determine_frame_type_with_data_availability():
        frame_types = ['FRAME_TYPE_A', 'FRAME_TYPE_B', 'FRAME_TYPE_C']
        data_available = random.choice([True, False])
        return {'frame_type': random.choice(frame_types), 'data_available': data_available}

    structures = []

    for _ in range(num_structs):
        socket_receive_uci_t = {
            'socket_id': get_random_socket_id(),
            'session_token': generate_session_token(),
            'frame_info': determine_frame_type_with_data_availability()
        }
        structures.append(socket_receive_uci_t)

    return structures
