def modular_exponentiation(text: str, modulus: int) -> int:
    if not (text.isdigit() or (text.isalpha() and all(c in 'ABCDEFGHIJKLMNOPQRSTUVWXYZ' for c in text))):
        raise ValueError(""Invalid input: 'text' must contain only digits or valid alphabetic characters."")

    if not isinstance(modulus, int) or modulus <= 0:
        raise ValueError(""Invalid input: 'modulus' must be a positive integer."")

    numerical_text = [ord(char) - ord('A') + 10 if char.isupper() else int(char) for char in text]

    result = 1
    base = numerical_text[0]

    for char_value in numerical_text[1:]:
        temp_result = result

        while char_value > 0:
            if char_value & 1:
                result = (result * base) % modulus

            base = (base * base) % modulus

            char_value >>= 1

    return result


