import random
import time

class CustomEventGenerator:
    def __init__(self, max_events=100):
        self.max_events = max_events
        self.events = []
        self.event_types = [""Login"", ""Purchase"", ""Signup"", ""Logout""]
        self.timestamp_format = ""%Y-%m-%d %H:%M:%S""

    def generate_id(self):
        if len(self.events) >= self.max_events:
            raise Exception(""Maximum array size exceeded"")
        return random.randint(1, 1000)

    def assign_unique_type(self):
        return random.choice(self.event_types)

    def set_timestamp(self):
        return time.strftime(self.timestamp_format, time.gmtime())

    def generate_event(self):
        id_ = self.generate_id()
        while id_ in [event['id'] for event in self.events]:
            id_ = self.generate_id()

        type_ = self.assign_unique_type()
        timestamp = self.set_timestamp()

        event = {
            'id': id_,
            'type': type_,
            'timestamp': timestamp,
            'details': f""Generated at {timestamp} with ID {id_} of type {type_}""
        }

        self.events.append(event)

    def display_events(self):
        for event in self.events:
            print(event['details'])

    def check_duplicate_ids(self):
        ids_set = set(event['id'] for event in self.events)

        if len(ids_set) != len(self.events):
            raise Exception(""Duplicate IDs detected"")

# Example usage
gen = CustomEventGenerator(5)
for _ in range(6):  # Attempt to generate 6 events with a limit of 5
    try:
        gen.generate_event()
    except Exception as e:
        print(f""Error: {e}"")

gen.display_events()

# Check for duplicate IDs after generation
try:
    gen.check_duplicate_ids()
