def update_tuple_list(input_list, target_str, add_str, case_sensitive=False, allow_updates=True):
    if not isinstance(input_list, list) or not all(isinstance(t, tuple) and len(t) == 3 for t in input_list):
        raise ValueError(""input_list must be a list of tuples with three elements each."")

    if not isinstance(target_str, str) or not target_str:
        raise ValueError(""target_str must be a non-empty string."")

    if not isinstance(add_str, str):
        raise ValueError(""add_str must be a string."")

    if not input_list:
        raise ValueError(""input_list cannot be empty."")

    cache = {}

    def find_index(lst, target, case_sensitive):
        if target in cache:
            return cache[target]
        for i, item in enumerate(lst):
            first_elem = item[0] if case_sensitive else item[0].lower()
            target_check = target if case_sensitive else target.lower()
            if first_elem == target_check:
                cache[target] = i
                return i
        return -1

    if not allow_updates:
        return

    index = find_index(input_list, target_str, case_sensitive)

    for item in input_list:
        if isinstance(item[2], int) and item[2] < 0:
            raise ValueError(""Integers within tuples must be non-negative."")

    if index != -1:
        first_elem = input_list[index][0]
        new_value = input_list[index][2] + len(input_list[index][1]) + len(add_str)
        input_list[index] = (first_elem, add_str, new_value)
    else:
        input_list.append((target_str, add_str, 0))

# Unit Tests
import unittest

class TestUpdateTupleList(unittest.TestCase):

    def setUp(self):
        self.list_with_tuples = [('apple', 'pie', 5), ('banana', 'split', 3)]

    def test_case_insensitive_match(self):
        update_tuple_list(self.list_with_tuples, 'APPLE', 'juice')
        self.assertEqual(self.list_with_tuples[0], ('apple', 'juice', 9))

    def test_no_existing_target(self):
        update_tuple_list(self.list_with_tuples, 'cherry', 'jam')
        self.assertEqual(self.list_with_tuples[-1], ('cherry', 'jam', 0))

    def test_case_sensitive_match(self):
        update_tuple_list(self.list_with_tuples, 'Banana', 'split', case_sensitive=True)
        self.assertEqual(self.list_with_tuples[1], ('banana', 'split', 11))

    def test_prevent_updates(self):
        update_tuple_list(self.list_with_tuples, 'apple', 'juice', allow_updates=False)
        self.assertNotEqual(self.list_with_tuples[0][2], 9)

if __name__ == '__main__':
    unittest.main()
