import socket
from collections import defaultdict

class Node:
    def __init__(self, value):
        self.value = value
        self.left = None
        self.right = None

class BST:
    def __init__(self):
        self.root = None

    def insert(self, value):
        if not self.root:
            self.root = Node(value)
            return
        current_node = self.root
        while True:
            if value < current_node.value:
                if current_node.left is None:
                    current_node.left = Node(value)
                    break
                else:
                    current_node = current_node.left
            else:
                if current_node.right is None:
                    current_node.right = Node(value)
                    break
                else:
                    current_node = current_node.right

    def find_disjoint(self, value):
        if not self.root or value is None or not isinstance(value, float):
            return False

        current_node = self.root
        while current_node:
            if current_node.value == value:
                return False
            elif value < current_node.value:
                current_node = current_node.left
            else:
                current_node = current_node.right
        return True

def resolve_dns(hostname):
    try:
        ip_address = socket.gethostbyname(hostname)
        return ip_address
    except socket.gaierror:
        return None

def calculate_disjoint_pairs(hostnames, floats_list):
    bst_disjoint_set_union = BST()
    disjoint_count = 0

    for hostname in hostnames:
        ip_address = resolve_dns(hostname)

        if ip_address is not None and isinstance(ip_address, str) and all(isinstance(x, float) for x in floats_list):
            # Convert IP address string to u_char array
            # (Python doesn't have 'u_char', so this is a conceptual step)

            # Insert floats into BST for disjointness checks
            for float_value in floats_list:
                if bst_disjoint_set_union.find_disjoint(float_value):
                    bst_disjoint_set_union.insert(float_value)
                    disjoint_count += 1

    return disjoint_count

