from time import perf_counter
from collections import deque, defaultdict
from typing import List

class Node:
    def __init__(self, val: float):
        self.val = val
        self.left = None
        self.right = None

def insert_node(root: Node, val: float) -> Node:
    if root is None:
        return Node(val)
    if val < root.val:
        root.left = insert_node(root.left, val)
    else:
        root.right = insert_node(root.right, val)
    return root

def in_range(node: Node, start: float, end: float) -> bool:
    if node is None:
        return False
    if start <= node.val <= end:
        return True
    return in_range(node.left, start, end) or in_range(node.right, start, end)

def calculate_time(func):
    def wrapper(numbers: List[float]):
        start_time = perf_counter()
        result = func(numbers)
        elapsed_time = (perf_counter() - start_time) * 1000000
        print(f""Time taken by {func.__name__}: {elapsed_time} microseconds"")
        return result
    return wrapper

@calculate_time
def count_disjoint_pairs(numbers: List[float], disjoint_pairs_count: int) -> int:
    numbers.sort()

    nodes_stack = deque()
    left_boundries_stack = []
    disjoint_pairs = 0

    for num in numbers:

        while nodes_stack and (not nodes_stack or not in_range(nodes_stack[-1], num - nodes_stack[-1].val, num + nodes_stack[-1].val)):
            left_boundries_stack.append(nodes_stack.pop())

        while left_boundries_stack and (not nodes_stack or not in_range(left_boundries_stack[-1], num - nodes_stack[-1].val, num + nodes_stack[-1].val)):
            left_boundries_stack.pop()

        for node in nodes_stack:
            if abs(node.val - num) <= disjoint_pairs_count:
                disjoint_pairs += 1

        root = None
        for boundary_node in left_boundries_stack:
            root = insert_node(root, boundary_node.val)

        root = insert_node(root, num)
        nodes_stack.append(Node(num))

    return disjoint_pairs
