import random
import string

def generate_dcr_messages(num_messages):
    def random_device_id(length=8):
        return ''.join(random.choices(string.ascii_uppercase + string.digits, k=length))

    def random_apn():
        return f""apn-{random.randint(1000, 9999)}""

    def random_ip_address():
        return '.'.join(str(random.randint(0, 255)) for _ in range(4))

    dcr_messages = []
    for _ in range(num_messages):
        device_id = random_device_id()
        apn = random_apn()
        ip_address = random_ip_address()
        dcr_message = {
            'DeviceID': device_id,
            'APN': apn,
            'IPAddress': ip_address
        }
        dcr_messages.append(dcr_message)

    return dcr_messages

# Example usage:
