class Individual:
    def __init__(self, id, height, successful_missions):
        self.id = id
        self.height = height
        self.successful_missions = successful_missions

def find_best_candidate(individuals):
    best_id = None
    highest_ratio = 0

    for individual in individuals:
        if individual.height < 180 and individual.successful_missions > 0:
            ratio = individual.successful_missions / (individual.successful_missions + 1)  # Assuming attempts are successful_missions + 1
            if ratio > highest_ratio:
                highest_ratio = ratio
                best_id = individual.id

    return best_id

def find_best_candidate_with_height_condition(individuals):
    best_id = None
    highest_ratio = 0

    for individual in individuals:
        if (170 <= individual.height <= 175) and individual.successful_missions > 0:
            ratio = individual.successful_missions / (individual.successful_missions + 1)
            if ratio > highest_ratio:
                highest_ratio = ratio
                best_id = individual.id

    return best_id

# Example usage:
people = [
    Individual(1, 175, 5),
    Individual(2, 182, 10),
    Individual(3, 170, 8),
    Individual(4, 178, 7)
]

print(find_best_candidate(people))  # Output: ID of the best candidate under 180 cm
print(find_best_candidate_with_height_condition(people))  # Output: ID with height between 170 and 175 cm
