            return False

        # Validate types of each field
        if not isinstance(data[""access_token""], str) or not isinstance(data[""token_type""], str):
            return False

        # Validate the range of ""expires_in""
        expires_in = data.get(""expires_in"")
        if not isinstance(expires_in, int) or not (300 <= expires_in <= 3600):
            return False

        return True
    except (json.JSONDecodeError, TypeError):
        return False
