import jwt
from datetime import datetime, timedelta
import logging

logging.basicConfig(filename='jwt_activity.log', level=logging.INFO)

# Dictionary to store blacklisted tokens
blacklist = {}

def generate_secret_key():
    return {
        'secret': jwt.encode({'dummy': 'payload'}, 'your-access-key').decode('utf-8'),
        'refresh_secret': jwt.encode({'dummy': 'payload'}, 'your-refresh-key').decode('utf-8')
    }

def create_access_token(user_info, custom_claims=None):
    payload = {
        'user_info': user_info,
        'exp': datetime.utcnow() + timedelta(hours=1)
    }

    if custom_claims:
        payload.update(custom_claims)

    secret_key = generate_secret_key()['secret']
    token = jwt.encode(payload=payload, key=secret_key, algorithm='HS256')

    logging.info(f""Access token created: {token}"")
    return token

def create_refresh_token(user_info):
    payload = {
        'user_info': user_info,
        'exp': datetime.utcnow() + timedelta(hours=12)
    }
    secret_key = generate_secret_key()['refresh_secret']
    refresh_token = jwt.encode(payload=payload, key=secret_key, algorithm='HS256')

    logging.info(f""Refresh token created: {refresh_token}"")
    return refresh_token

def verify_and_decode(token, secret_key):
    try:
        decoded_payload = jwt.decode(token, secret_key, algorithms=['HS256'])
        if token in blacklist.get('access', []):
            raise jwt.InvalidTokenError(""Token has been blacklisted"")

        logging.info(f""Token verified: {token}"")
        return decoded_payload
    except jwt.ExpiredSignatureError:
        logging.error(f""Token expired: {token}"")
        raise ValueError(""Token has expired"")
    except jwt.InvalidTokenError as e:
        logging.error(f""Invalid token error: {e} - Token: {token}"")
        raise ValueError(""Invalid token"")

def blacklist_access_token(token):
    if 'access' not in blacklist:
        blacklist['access'] = []

    blacklist['access'].append(token)
    logging.info(f""Token blacklisted: {token}"")

def refresh_access_token(refresh_token, user_info):
    try:
        secret_key = generate_secret_key()['refresh_secret']
        verify_and_decode(refresh_token, secret_key)  # Verify refresh token
        return create_access_token(user_info)  # Create new access token
    except ValueError as e:
        logging.error(f""Failed to refresh access token: {e}"")
        raise

# Example integration with OAuth providers
def authenticate_via_oauth(provider):
    if provider == 'google':
        # Implement Google OAuth logic here
        pass
    elif provider == 'facebook':
        # Implement Facebook OAuth logic here
        pass
    else:
        logging.error(f""Unsupported OAuth provider: {provider}"")
        raise ValueError(""Unsupported OAuth provider"")

# Example usage (Not part of the program, just for illustration)
if __name__ == ""__main__"":
    user_info = {'user_id': 123, 'email': 'test@example.com'}
    access_token = create_access_token(user_info)
    refresh_token = create_refresh_token(user_info)

    try:
        decoded_payload = verify_and_decode(access_token, generate_secret_key()['secret'])
        print(decoded_payload)
    except ValueError as e:
        print(e)

    # Blacklist the token after logout
    blacklist_access_token(access_token)

    # Refresh access token using refresh token
    new_access_token = refresh_access_token(refresh_token, user_info)
    print(new_access_token)
