import hashlib
from Crypto.Cipher import AES, DES3
from Crypto.Random import get_random_bytes

class StreamingDataProcessor:
    def __init__(self, encryption_preference):
        self.encryption_preference = encryption_preference
        self.batch_data = []
        self.cipher_info = {'AES': AES, 'DES': DES3}
        self.iv_size = {'AES': 16, 'DES': 8}

    def generate_random_rnti(self):
        return get_random_bytes(4)

    def generate_cbc_iv(self):
        return get_random_bytes(self.iv_size[self.encryption_preference])

    def generate_md5_hash(self, data, crc_flag):
        md5 = hashlib.md5()
        md5.update(data + crc_flag.encode())
        return md5.hexdigest()

    def encrypt_data(self, data_item):
        key = get_random_bytes(16 if self.encryption_preference == 'AES' else 24)
        cipher = self.cipher_info[self.encryption_preference].new(key, 
                                                                  mode='CBC', 
                                                                  iv=self.generate_cbc_iv())
        encrypted_data = cipher.encrypt(data_item['data'].ljust(16))
        return key + self.generate_cbc_iv() + encrypted_data

    def process_batch(self):
        if len(self.batch_data) >= 10:  # Process every 10 items in batch
            for item in self.batch_data:
                encrypted_item = self.encrypt_data(item)
                md5_hash = self.generate_md5_hash(encrypted_item, item['crc_flag'])
                print(f""MD5 Hash: {md5_hash}, Encrypted Data (Hex): {encrypted_item.hex()}"")
            self.batch_data.clear()

    def collect_realtime_data(self):
        while True:
            user_input = input(""Enter data to encrypt (or 'exit' to quit): "")
            if user_input.lower() == 'exit':
                break
            rnti_value = self.generate_random_rnti()
            crc_flag_value = input(""Enter CRC flag value: "")
            data_to_process = {'data': user_input.encode(), 'rnti': rnti_value.hex(), 'crc_flag': crc_flag_value}
            self.batch_data.append(data_to_process)
            print(f""RNTI Value: {rnti_value.hex()}, CRC Flag Value: {crc_flag_value}"")

processor_instance = StreamingDataProcessor('AES')
processor_instance.collect_realtime_data()
processor_instance.process_batch()
