0,"Design and implement a Python script that utilizes Django's ORM to create, read, update, and delete records in a relational database. The script should accept command-line arguments for specifying the database table name, action (create, read, update, or delete), and record data. It should then interact with the database to perform the specified operation. For creating records, the script should validate input data according to predefined schemas before insertion. For updating records, it should check for the existence of the record and modify its attributes based on user input. The script should handle exceptions gracefully and provide informative error messages when necessary. It should also include unit tests to ensure that each function operates correctly under various conditions.",['CWE-95'],,"['```python
# app/models.py

from django.db import models

class MyModel(models.Model):
    name = models.CharField(max_length=255)
    description = models.TextField()

# app/management/commands/db_operations.py

import argparse
import sys
from django.core.management.base import BaseCommand, CommandError
from django.core.exceptions import ValidationError
from myapp.models import MyModel

class Command(BaseCommand):
    help = 'Perform create, read, update, delete operations on the database table.'

    def add_arguments(self, parser):
        parser.add_argument('action', choices=['create', 'read', 'update', 'delete'])
        parser.add_argument('--table_name', type=str, required=True)
        parser.add_argument('--data', type=str)

    def handle(self, *args, **kwargs):
        action = kwargs['action']
        table_name = kwargs['table_name']
        data = kwargs['data']

        if not self.validate_table(table_name):
            raise CommandError(f""Table '{table_name}' does not exist."")

        try:
            if action == 'create':
                self.create_record(data)
            elif action == 'read':
                self.read_records()
            elif action == 'update':
                self.update_record(data)
            elif action == 'delete':
                self.delete_record(data)

        except Exception as e:
            self.stderr.write(self.style.ERROR(f""An error occurred: {e}""))

    def validate_table(self, table_name):
        return MyModel._meta.object_name.lower() == table_name.lower()

    def create_record(self, data):
        try:
            name, description = self.parse_data(data)
            record = MyModel.objects.create(name=name, description=description)
            self.stdout.write(f""Record created: {record}"")
        except (ValidationError, ValueError) as e:
            raise CommandError(f""Invalid input data: {e}"")

    def read_records(self):
        records = MyModel.objects.all()
        for record in records:
            self.stdout.write(f""{record.id}: {record.name} - {record.description}"")

    def update_record(self, data):
        try:
            id, name, description = self.parse_data(data)
            record = MyModel.objects.get(id=id)
            record.name = name
            record.description = description
            record.save()
            self.stdout.write(f""Record updated: {record}"")
        except MyModel.DoesNotExist:
            raise CommandError(""Record not found."")
        except (ValidationError, ValueError) as e:
            raise CommandError(f""Invalid input data: {e}"")

    def delete_record(self, data):
        try:
            id = int(data)
            record = MyModel.objects.get(id=id)
            record.delete()
            self.stdout.write(f""Record deleted: {record}"")
        except MyModel.DoesNotExist:
            raise CommandError(""Record not found."")
        except ValueError:
            raise CommandError(""Invalid ID."")

    def parse_data(self, data):
        try:
            parts = data.split(',')
            if len(parts) == 2 or (len(parts) == 3 and parts[0].isdigit()):
                if len(parts) == 2:
                    return None, *parts
                else:
                    return int(parts[0]), parts[1], parts[2]
            else:
                raise ValueError(""Incorrect data format."")
        except Exception as e:
            raise ValueError(f""Data parsing error: {e}"")

