from django.test import TestCase
from myapp.models import MyModel

class MyModelTestCase(TestCase):
    def setUp(self):
        MyModel.objects.create(name=""Test"", description=""Test Description"")

    def test_create_record(self):
        record_count = MyModel.objects.count()
        new_record = MyModel.objects.create(name=""New Test"", description=""New Description"")
        self.assertEqual(MyModel.objects.count(), record_count + 1)

    def test_read_records(self):
        records = list(MyModel.objects.all())
        self.assertGreater(len(records), 0)

    def test_update_record(self):
        record = MyModel.objects.first()
        original_description = record.description
        record.description = ""Updated Description""
        record.save()
        updated_record = MyModel.objects.get(id=record.id)
        self.assertNotEqual(updated_record.description, original_description)

    def test_delete_record(self):
        record_count = MyModel.objects.count()
        MyModel.objects.all().delete()
        self.assertEqual(MyModel.objects.count(), 0)
