import time
import random

class Daemon:
    def __init__(self):
        self.active = False

    def activate(self):
        self.active = True
        print(""Daemon activated"")

    def deactivate(self):
        self.active = False
        print(""Daemon deactivated"")
        notify_alert_system()

def notify_alert_system():
    # Simulate notifying an alert system
    print(""Notification sent to alert system"")

def main():
    daemon = Daemon()

    while True:
        if not daemon.active:
            time.sleep(random.uniform(1, 5))  # Random interval between activations
            daemon.activate()

        time.sleep(random.uniform(2, 4))  # Random interval before deactivation
        daemon.deactivate()

if __name__ == ""__main__"":
    main()
