def filter_and_sort_dict(original_dict, keys_list, sort_func):
    try:
        # Extract values corresponding to the specified keys
        extracted_values = [original_dict[key] for key in keys_list if key in original_dict]

        # Check if any key was missing from the original dictionary
        if len(extracted_values) != len(keys_list):
            return None

        # Sort the extracted values using the provided sorting function
        sorted_values = sorted(extracted_values, key=sort_func)

        # Create a new dictionary with keys and their corresponding sorted values
        result_dict = {key: value for key, value in zip(keys_list, sorted_values)}

        return result_dict

    except MemoryError:
        return None
