import json

def process_json(json_string, query_key=None, extraction_type='key', filter_condition=None, num_objects=1, return_type='list'):
    data = json.loads(json_string)

    if isinstance(data, dict):
        data = [data]

    extracted_data = []

    for item in data:
        try:
            if query_key and query_key in item:
                value_to_check = item[query_key] if extraction_type == 'key' else item
                if filter_condition is None or filter_condition(value_to_check):
                    extracted_data.append(item if extraction_type == 'value' else value_to_check)

            elif not query_key:  # If no specific key, process all keys/values based on extraction type
                for k, v in (item.items() if extraction_type == 'key' else [(v, k) for k, v in item.items()]):
                    if filter_condition is None or filter_condition(v):
                        extracted_data.append(k if extraction_type == 'key' else v)
        except Exception as e:
            continue  # Skip items that cause exceptions

        if len(extracted_data) >= num_objects:
            break

    if return_type == 'list':
        return extracted_data[:num_objects]
    elif return_type == 'dict':
        return {i: extracted_data[i] for i in range(min(num_objects, len(extracted_data)))}

# Example usage
json_string = '[{""name"": ""Alice"", ""age"": 30}, {""name"": ""Bob"", ""age"": 25}]'
