import random
import string

class Location:
    def __init__(self, latitude, longitude):
        self.latitude = latitude
        self.longitude = longitude

class UserProfile:
    def __init__(self, user_id, age, email, active, locations, tsn_frames):
        self.user_id = user_id
        self.age = age
        self.email = email
        self.active = active
        self.locations = locations
        self.tsn_frames = tsn_frames

class TSNFrame:
    def __init__(self, timestamp, mac_address, vlan_id):
        self.timestamp = timestamp
        self.mac_address = mac_address
        self.vlan_id = vlan_id

def generate_random_mac():
    return "":"".join(""{:02X}"".format(random.randint(0, 255)) for _ in range(6))

def generate_user_profile(user_id):
    age = random.randint(18, 70)
    username = ''.join(random.choices(string.ascii_lowercase + string.digits, k=8))
    email = f""{username}@example.com""
    active = bool(random.getrandbits(1))

    # Generate a random location within specified geographic bounds
    latitude = round(random.uniform(-90.0, 90.0), 6)
    longitude = round(random.uniform(-180.0, 180.0), 6)
    locations = [Location(latitude, longitude)]

    # Create TSNFrames for the user
    tsn_frames = [
        TSNFrame(
            timestamp=random.randint(0, 1000),
            mac_address=generate_random_mac(),
            vlan_id=random.randint(1, 4094)
        ) for _ in range(random.randint(1, 10))
    ]

    return UserProfile(user_id, age, email, active, locations, tsn_frames)

def generateTSNUserProfile(num_users):
    return [generate_user_profile(user_id) for user_id in range(1, num_users + 1)]
