```python
import time
import random

class SensorReading:
    def __init__(self, timestamp, temperature, humidity):
        self.timestamp = timestamp
        self.temperature = temperature
        self.humidity = humidity

class EmitterLogEntry:
    def __init__(self, device_id):
        self.device_id = device_id

def generate_sensor_readings(num_readings):
    MAX_SENSOR_ARRAY_SIZE = 1000
    sensor_array = []
    emitter_log = {}

    for _ in range(num_readings):
        if len(sensor_array) >= MAX_SENSOR_ARRAY_SIZE:
            raise MemoryError(""Exceeded maximum capacity of sensor readings array."")

        # Generate unique device ID
        while True:
            device_id = random.randint(1, 1000000)
            if device_id not in emitter_log:
                emitter_log[device_id] = EmitterLogEntry(device_id)
                break

        # Create a new SensorReading
        new_reading = SensorReading(
            timestamp=time.time(),
            temperature=random.uniform(-273.15, 100),
            humidity=random.uniform(0, 100)
        )

        # Ensure uniqueness (example: checking for duplicate readings - optional based on requirements)
        if any(sr.timestamp == new_reading.timestamp and 
               sr.temperature == new_reading.temperature and
               sr.humidity == new_reading.humidity for sr in sensor_array):
            continue

        sensor_array.append(new_reading)

    return sensor_array, list(emitter_log.values())

# Example usage:
try:
    readings, log_entries = generate_sensor_readings(500)
    print(f""Generated {len(readings)} sensor readings."")
except MemoryError as e:
    print(e)
```

