import hashlib
import re

def calculate_md5_hash(text):
    hash_object = hashlib.md5()
    hash_object.update(text.encode('utf-8'))
    return hash_object.hexdigest()

def apply_formatting(line, format_rules):
    for rule in format_rules:
        pattern, replacement = rule.split('|')
        line = re.sub(pattern, replacement, line)
    return line.strip()

def process_file(input_file_name, output_file_name, format_rules):
    with open(input_file_name) as input_file:
        lines = []
        for line in input_file:
            transformed_line = apply_formatting(line.strip(), format_rules)
            segments = [transformed_line[i:i+1024] for i in range(0, len(transformed_line), 1024)]
            hashes = [calculate_md5_hash(segment) for segment in segments]
            lines.extend(zip(segments, hashes))

    with open(output_file_name, 'w') as output_file:
        for segment_with_hash in lines:
            output_file.write(f""{segment_with_hash[0]} ({segment_with_hash[1]})\n"")

