import time
import random

class SensorReading:
    def __init__(self, timestamp, temperature, humidity):
        self.timestamp = timestamp
        self.temperature = temperature
        self.humidity = humidity

    def __eq__(self, other):
        return (self.timestamp == other.timestamp and 
                self.temperature == other.temperature and 
                self.humidity == other.humidity)

    def __hash__(self):
        return hash((self.timestamp, self.temperature, self.humidity))

class EmitterLogEntry:
    def __init__(self, device_id):
        self.device_id = device_id

def generate_sensor_readings(num_readings):
    MAX_SENSOR_ARRAY_SIZE = 1000
    sensor_array = set()

    # Generate random readings ensuring uniqueness
    while len(sensor_array) < num_readings and len(sensor_array) < MAX_SENSOR_ARRAY_SIZE:
        try:
            timestamp = time.time() + random.uniform(-10000, 0)
            temperature = random.uniform(-273.15, 100)
            humidity = random.uniform(0, 100)

            sensor_reading = SensorReading(timestamp, temperature, humidity)
            sensor_array.add(sensor_reading)

        except MemoryError:
            print(""Memory allocation error occurred."")
            break

    # Check if we've managed to generate the required number of readings
    if len(sensor_array) < num_readings:
        raise ValueError(f""Could not allocate {num_readings} unique SensorReadings within memory constraints."")

    return list(sensor_array)

def generate_emitter_log_entries(num_entries):
    emitter_log = set()

    while len(emitter_log) < num_entries:
        try:
            device_id = random.randint(1000, 9999)
            emitter_log_entry = EmitterLogEntry(device_id)

            # Ensure the uniqueness of each Device ID
            if emitter_log_entry not in emitter_log:
                emitter_log.add(emitter_log_entry)

        except MemoryError:
            print(""Memory allocation error occurred."")
            break

    # Check if we've managed to generate the required number of entries
    if len(emitter_log) < num_entries:
        raise ValueError(f""Could not allocate {num_entries} unique EmitterLogEntries within memory constraints."")

    return list(emitter_log)

# Example usage:
sensor_readings = generate_sensor_readings(500)
emitter_log_entries = generate_emitter_log_entries(50)

print(""Generated Sensor Readings:"", sensor_readings)
print(""Generated Emitter Log Entries:"", emitter_log_entries)
